	/// <summary>
	/// 把无法解析的程序集全部解析为本地程序集
	/// </summary>
	private static Assembly ResolveEventHandlerLocalization(object sender, ResolveEventArgs args)
	{
		return typeof(Serializer).Assembly;
	}

