	/// <summary>
	/// 序列化二进制数据块的全部数据.
	/// 写入的数据大小可以超出限制.
	/// </summary>
	/// <param name="block"></param>
	/// <param name="dataPool"></param>
	/// <returns>序列化的数据的起始偏移</returns>
	public unsafe static int SerializeModifications(IBinary block, RawDataPool dataPool)
	{
		int dataSize = block.GetSize();
		ushort metadataSize = block.GetSerializedFixedSizeOfMetadata();
		byte* pData = default(byte*);
		int result = dataPool.Allocate(8 + dataSize + metadataSize, &pData);
		*pData = 0;
		pData += 4;
		*(int*)pData = dataSize;
		pData += 4;
		block.CopyTo(0, dataSize, pData);
		pData += dataSize;
		block.SerializeMetadata(pData);
		return result;
	}

	/// <summary>
	/// 序列化二进制数据块的数据改动.
	/// 写入的数据大小可以超出限制.
	/// </summary>
	/// <param name="block"></param>
	/// <param name="dataPool"></param>
	/// <param name="modifications">修改记录. 虽然是值类型, 但由于不需要修改, 因此不用按引用传递.</param>
	/// <returns>序列化的数据的起始偏移</returns>
	public unsafe static int SerializeModifications(IBinary block, RawDataPool dataPool, BinaryModificationCollection modifications)
	{
		int recordsCount = modifications.Items.Count;
		byte* pData = default(byte*);
		int result = dataPool.Allocate(4, &pData);
		*pData = 1;
		pData[1] = ((recordsCount > 0) ? ((byte)1) : ((byte)0));
		(pData + 1)[1] = (modifications.MetadataModified ? ((byte)1) : ((byte)0));
		if (recordsCount > 0)
		{
			dataPool.AddUnmanaged(block.GetSize());
			Fragments.Clear();
			GenerateOriginalDataFragments(modifications.OriSize, modifications.Items, Fragments);
			WriteFragments(Fragments, dataPool);
			int syncDataSizeOffset = dataPool.Allocate(4, &pData);
			GenerateSyncData(block, Fragments, dataPool);
			pData = dataPool.GetPointer(syncDataSizeOffset);
			*(int*)pData = dataPool.GetWrittenDataSize(syncDataSizeOffset) - 4;
		}
		if (modifications.MetadataModified)
		{
			dataPool.Allocate(block.GetSerializedFixedSizeOfMetadata(), &pData);
			block.SerializeMetadata(pData);
		}
		return result;
	}

	public unsafe static int DeserializeModifications(RawDataPool dataPool, int offset, IBinary block, List<(int offset, int size)> newDataInfos)
	{
		byte* pData = dataPool.GetPointer(offset);
		if (*pData == 1)
		{
			byte* pCurrData = pData;
			byte num = pCurrData[1];
			bool modifiedMetadata = (pCurrData + 1)[1] != 0;
			pCurrData += 4;
			if (num != 0)
			{
				int currDataSize = *(int*)pCurrData;
				pCurrData += 4;
				Fragments.Clear();
				pCurrData += ReadFragments(pCurrData, Fragments);
				int syncDataSize = *(int*)pCurrData;
				pCurrData += 4;
				SyncBinary(block, currDataSize, Fragments, pCurrData, syncDataSize, newDataInfos);
				pCurrData += syncDataSize;
			}
			if (modifiedMetadata)
			{
				pCurrData += block.DeserializeMetadata(pCurrData);
			}
			return (int)(pCurrData - pData);
		}
		block.Clear();
		byte* pCurrData2 = pData;
		pCurrData2 += 4;
		int dataSize = *(int*)pCurrData2;
		pCurrData2 += 4;
		block.Write(pCurrData2, 0, dataSize);
		pCurrData2 += dataSize;
		pCurrData2 += block.DeserializeMetadata(pCurrData2);
		newDataInfos?.Add((0, dataSize));
		return (int)(pCurrData2 - pData);
	}

	/// <summary>
	/// 从修改记录构造原数据碎片.
	/// 即计算出原数据被打散后, 各部分在最终数据中的位置.
	/// </summary>
	/// <param name="oriSize">原数据的大小</param>
	/// <param name="records"></param>
	/// <param name="fragments">已排序的原数据碎片集合</param>
	private static void GenerateOriginalDataFragments(int oriSize, List<BinaryModification> records, List<OriginalDataFragment> fragments)
	{
		fragments.Add(new OriginalDataFragment(0, oriSize, 0));
		int i = 0;
		for (int count = records.Count; i < count; i++)
		{
			BinaryModification record = records[i];
			switch (record.Type)
			{
			case 0:
				OriginalDataFragmentsHelper.ApplyInsertRecord(fragments, record.Offset, record.Size);
				break;
			case 1:
				OriginalDataFragmentsHelper.ApplyWriteRecord(fragments, record.Offset, record.Size);
				break;
			case 2:
				OriginalDataFragmentsHelper.ApplyDeleteRecord(fragments, record.Offset, record.Size);
				break;
			}
		}
	}

	/// <summary>
	/// 把原数据碎片写入到数据池
	/// </summary>
	/// <param name="fragments"></param>
	/// <param name="dataPool"></param>
	private unsafe static void WriteFragments(List<OriginalDataFragment> fragments, RawDataPool dataPool)
	{
		int fragmentsCount = fragments.Count;
		byte* pData = default(byte*);
		dataPool.Allocate(4 + fragmentsCount * sizeof(OriginalDataFragment), &pData);
		*(int*)pData = fragmentsCount;
		pData += 4;
		for (int i = 0; i < fragmentsCount; i++)
		{
			*(OriginalDataFragment*)pData = fragments[i];
			pData += sizeof(OriginalDataFragment);
		}
	}

	/// <summary>
	/// 从内存中读取原数据碎片
	/// </summary>
	/// <param name="fragments"></param>
	/// <param name="pData"></param>
	private unsafe static int ReadFragments(byte* pData, List<OriginalDataFragment> fragments)
	{
		byte* pCurrData = pData;
		int fragmentsCount = *(int*)pCurrData;
		pCurrData += 4;
		for (int i = 0; i < fragmentsCount; i++)
		{
			OriginalDataFragment fragment = *(OriginalDataFragment*)pCurrData;
			fragments.Add(fragment);
			pCurrData += sizeof(OriginalDataFragment);
		}
		return (int)(pCurrData - pData);
	}

	/// <summary>
	/// 根据现有数据和碎片集合, 构造同步数据
	/// </summary>
	/// <param name="currBlock">当前数据块</param>
	/// <param name="fragments">已排序的原数据碎片集合</param>
	/// <param name="dataPool">
	/// 此方法会写入一个同步数据列表到数据池中, 其元素为: 若要更新到当前数据, 应该设置的数据及其位置.
	/// 元素数据结构: offset (int), size (int), data.
	/// </param>
	private static void GenerateSyncData(IBinary currBlock, List<OriginalDataFragment> fragments, RawDataPool dataPool)
	{
		int currOffset = 0;
		int i = 0;
		for (int count = fragments.Count; i < count; i++)
		{
			OriginalDataFragment fragment = fragments[i];
			if (currOffset < fragment.CurrOffset)
			{
				AddSyncData(dataPool, currBlock, currOffset, fragment.CurrOffset - currOffset);
			}
			else if (currOffset > fragment.CurrOffset)
			{
				throw new Exception("Malformed fragments");
			}
			currOffset = fragment.CurrOffset + fragment.Size;
		}
		int currSize = currBlock.GetSize();
		if (currOffset < currSize)
		{
			AddSyncData(dataPool, currBlock, currOffset, currSize - currOffset);
		}
	}

	/// <summary>
	/// 添加同步数据.
	/// 同步数据结构: offset (int), size (int), data.
	/// </summary>
	/// <param name="dataPool"></param>
	/// <param name="currBlock"></param>
	/// <param name="offset"></param>
	/// <param name="size"></param>
	private unsafe static void AddSyncData(RawDataPool dataPool, IBinary currBlock, int offset, int size)
	{
		byte* pData = default(byte*);
		dataPool.Allocate(8 + size, &pData);
		*(int*)pData = offset;
		((int*)pData)[1] = size;
		currBlock.CopyTo(offset, size, pData + 4 + 4);
	}

	private unsafe static void SyncBinary(IBinary block, int currDataSize, List<OriginalDataFragment> fragments, byte* pSyncData, int syncDataSize, List<(int offset, int size)> newDataInfos)
	{
		sbyte fragmentsMovingMethod = CalcFragmentsMovingMethod(fragments);
		switch (fragmentsMovingMethod)
		{
		case 0:
			MoveFragmentsInPlaceForward(block, fragments, currDataSize);
			break;
		case 1:
			MoveFragmentsInPlaceBackward(block, fragments, currDataSize);
			break;
		case 2:
			ReconstructFromFragments(block, fragments, currDataSize);
			break;
		default:
			throw new Exception($"Unsupported fragmentsMovingMethod: {fragmentsMovingMethod}");
		}
		RestructureFromSyncData(block, pSyncData, syncDataSize, newDataInfos);
	}

	/// <summary>
	/// 根据碎片数据选择移动原数据的方式.
	/// 当所有原数据都向后移时, 可以逆序原地移动; 当所有原数据都向前移时, 可以正序原地移动; 当完全没有规律时, 只能重建数据.
	/// </summary>
	/// <param name="fragments"></param>
	/// <returns>0: 正序原地移动, 1: 逆序原地移动, 2: 重建数据</returns>
	private static sbyte CalcFragmentsMovingMethod(List<OriginalDataFragment> fragments)
	{
		int fragmentsCount = fragments.Count;
		if (fragmentsCount <= 1)
		{
			return 0;
		}
		int forwardCount = 0;
		int backwardCount = 0;
		for (int i = 0; i < fragmentsCount; i++)
		{
			OriginalDataFragment fragment = fragments[i];
			if (fragment.CurrOffset > fragment.OriOffset)
			{
				forwardCount++;
			}
			else if (fragment.CurrOffset < fragment.OriOffset)
			{
				backwardCount++;
			}
		}
		if (backwardCount == 0)
		{
			return 0;
		}
		if (forwardCount == 0)
		{
			return 1;
		}
		return 2;
	}

	/// <summary>
	/// 正序原地移动原数据
	/// </summary>
	/// <param name="block"></param>
	/// <param name="fragments"></param>
	/// <param name="currDataSize"></param>
	private unsafe static void MoveFragmentsInPlaceForward(IBinary block, List<OriginalDataFragment> fragments, int currDataSize)
	{
		block.EnsureCapacity(currDataSize);
		fixed (byte* pRawData = block.GetRawData())
		{
			int i = 0;
			for (int count = fragments.Count; i < count; i++)
			{
				OriginalDataFragment fragment = fragments[i];
				Buffer.MemoryCopy(pRawData + fragment.OriOffset, pRawData + fragment.CurrOffset, fragment.Size, fragment.Size);
			}
		}
	}

	/// <summary>
	/// 逆序原地移动原数据
	/// </summary>
	/// <param name="block"></param>
	/// <param name="fragments"></param>
	/// <param name="currDataSize"></param>
	private unsafe static void MoveFragmentsInPlaceBackward(IBinary block, List<OriginalDataFragment> fragments, int currDataSize)
	{
		block.EnsureCapacity(currDataSize);
		fixed (byte* pRawData = block.GetRawData())
		{
			for (int i = fragments.Count - 1; i >= 0; i--)
			{
				OriginalDataFragment fragment = fragments[i];
				Buffer.MemoryCopy(pRawData + fragment.OriOffset, pRawData + fragment.CurrOffset, fragment.Size, fragment.Size);
			}
		}
	}

	/// <summary>
	/// 把原数据中的碎片复制到新的数据块, 之后再设置回原对象
	/// </summary>
	/// <param name="block"></param>
	/// <param name="fragments"></param>
	/// <param name="currDataSize"></param>
	private unsafe static void ReconstructFromFragments(IBinary block, List<OriginalDataFragment> fragments, int currDataSize)
	{
		byte[] rawData = new byte[currDataSize];
		fixed (byte* pOriData = block.GetRawData())
		{
			fixed (byte* pDestData = rawData)
			{
				int i = 0;
				for (int count = fragments.Count; i < count; i++)
				{
					OriginalDataFragment fragment = fragments[i];
					Buffer.MemoryCopy(pOriData + fragment.OriOffset, pDestData + fragment.CurrOffset, fragment.Size, fragment.Size);
				}
			}
		}
		block.SetRawData(rawData);
	}

	private unsafe static void RestructureFromSyncData(IBinary block, byte* pSyncData, int syncDataSize, List<(int offset, int size)> newDataInfos)
	{
		byte* pCurrSrc = pSyncData;
		byte* pEndSrc = pSyncData + syncDataSize;
		fixed (byte* pDestData = block.GetRawData())
		{
			while (pCurrSrc < pEndSrc)
			{
				int offset = *(int*)pCurrSrc;
				int size = ((int*)pCurrSrc)[1];
				Buffer.MemoryCopy(pCurrSrc + 4 + 4, pDestData + offset, size, size);
				pCurrSrc += 8 + size;
				newDataInfos?.Add((offset, size));
			}
		}
		if (pCurrSrc != pEndSrc)
		{
			throw new Exception("Malformed syncData");
		}
	}

	/// <summary>
	/// 深度复制一个实现了 ISerializableGameData 的对象
	/// </summary>
	/// <param name="obj"></param>
	/// <typeparam name="T"></typeparam>
	/// <returns></returns>
	public unsafe static T CreateCopy<T>(T obj) where T : ISerializableGameData, new()
	{
		T newObj = new T();
		int size = obj.GetSerializedSize();
		if (size < 1024)
		{
			byte* pData = stackalloc byte[(int)(uint)size];
			obj.Serialize(pData);
			newObj.Deserialize(pData);
		}
		else
		{
			fixed (byte* pData2 = new byte[size])
			{
				obj.Serialize(pData2);
				newObj.Deserialize(pData2);
			}
		}
		return newObj;
	}

	/// <summary>
	/// 深度复制一个实现了 ISerializableGameData 的对象
	/// </summary>
	public unsafe static void CopyTo<T>(ref T src, ref T dst) where T : ISerializableGameData
	{
		int size = src.GetSerializedSize();
		if (size < 1024)
		{
			byte* pData = stackalloc byte[(int)(uint)size];
			src.Serialize(pData);
			dst.Deserialize(pData);
		}
		else
		{
			fixed (byte* pData2 = new byte[size])
			{
				src.Serialize(pData2);
				dst.Deserialize(pData2);
			}
		}
	}

	private unsafe static int SerializeTuple<T>((T, T) item, RawDataPool dataPool) where T : unmanaged
	{
		byte* pData = default(byte*);
		int result = dataPool.Allocate(sizeof(T) * 2, &pData);
		*(T*)pData = item.Item1;
		((T*)pData)[1] = item.Item2;
		return result;
	}

	private unsafe static int DeserializeTuple<T>(RawDataPool dataPool, int offset, ref (T, T) item) where T : unmanaged
	{
		byte* pData = dataPool.GetPointer(offset);
		item.Item1 = *(T*)pData;
		item.Item2 = ((T*)pData)[1];
		return sizeof(T) * 2;
	}

	public unsafe static int SerializeAs<TSrc, TDst>(TSrc item, RawDataPool dataPool, Func<TSrc, TDst> converter) where TDst : ISerializableGameData
	{
		if (item != null)
		{
			TDst newItem = converter(item);
			int dataSize = newItem.GetSerializedSize();
			byte* pData = default(byte*);
			int result = dataPool.AllocateWithHeader(dataSize, &pData, (uint)dataSize);
			byte* pData2 = pData;
			newItem.Serialize(pData2);
			return result;
		}
		return dataPool.AddWithHeader(null, 0, 0u);
	}

	public unsafe static int DeserializeAs<TSrc, TDst>(RawDataPool dataPool, int offset, ref TSrc item, Func<TDst, TSrc> converter) where TDst : ISerializableGameData, new()
	{
		int dataSize = default(int);
		byte* pData = dataPool.GetPointerWithHeader(offset, (uint*)(&dataSize));
		if (dataSize > 0)
		{
			TDst newItem = new TDst();
			newItem.Deserialize(pData);
			item = converter(newItem);
			return 4 + dataSize;
		}
		item = default(TSrc);
		return 4;
	}

	public unsafe static int SerializeListAs<TSrc, TDst>(List<TSrc> item, RawDataPool dataPool, Func<TSrc, TDst> converter) where TDst : ISerializableGameData
	{
		if (item != null && item.Count > 0)
		{
			int dataSize = 0;
			int elementsCount = item.Count;
			for (int i = 0; i < elementsCount; i++)
			{
				TDst element = converter(item[i]);
				dataSize = ((element == null) ? (dataSize + 4) : (dataSize + (4 + element.GetSerializedSize())));
			}
			byte* pData = default(byte*);
			int offset = dataPool.AllocateWithHeader(dataSize, &pData, (uint)elementsCount);
			for (int j = 0; j < elementsCount; j++)
			{
				TSrc element2 = item[j];
				if (element2 != null)
				{
					byte* intPtr = pData;
					pData += 4;
					int subDataSize = converter(element2).Serialize(pData);
					pData += subDataSize;
					*(int*)intPtr = subDataSize;
				}
				else
				{
					*(int*)pData = 0;
					pData += 4;
				}
			}
			return offset;
		}
		return dataPool.AddWithHeader(null, 0, 0u);
	}

	public unsafe static int DeserializeListAs<TSrc, TDst>(RawDataPool dataPool, int offset, Func<TDst, TSrc> converter, ref List<TSrc> item) where TDst : ISerializableGameData, new()
	{
		int elementsCount = default(int);
		byte* pData = dataPool.GetPointerWithHeader(offset, (uint*)(&elementsCount));
		if (elementsCount > 0)
		{
			if (item == null)
			{
				item = new List<TSrc>();
			}
			else
			{
				item.Clear();
			}
			int destElementsCount = item.Count;
			if (elementsCount < destElementsCount)
			{
				item.RemoveRange(elementsCount, destElementsCount - elementsCount);
			}
			byte* pCurrData = pData;
			for (int i = 0; i < elementsCount; i++)
			{
				int num = *(int*)pCurrData;
				pCurrData += 4;
				if (num > 0)
				{
					TDst element = new TDst();
					pCurrData += element.Deserialize(pCurrData);
					item.Add(converter(element));
				}
				else
				{
					item.Add(default(TSrc));
				}
			}
			return 4 + (int)(pCurrData - pData);
		}
		item?.Clear();
		return 4;
	}

	[ExtraSerializer]
	public static int Serialize((int, int) item, RawDataPool dataPool)
	{
		return SerializeTuple(item, dataPool);
	}

	[ExtraSerializer]
	public static int Deserialize(RawDataPool dataPool, int offset, ref (int, int) item)
	{
		return DeserializeTuple(dataPool, offset, ref item);
	}

	[ExtraSerializer]
