	[ExtraSerializer]
	public unsafe static int Serialize((ItemSourceType type, List<ItemDisplayData> list) tuple, RawDataPool dataPool)
	{
		int dataSize = 8;
		if (tuple.list != null)
		{
			foreach (ItemDisplayData data in tuple.list)
			{
				dataSize += data.GetSerializedSize();
			}
		}
		byte* pData = default(byte*);
		int offset = dataPool.Allocate(dataSize, &pData);
		*(ItemSourceType*)pData = tuple.type;
		pData += 4;
		*(int*)pData = tuple.list?.Count ?? 0;
		pData += 4;
		if (tuple.list != null)
		{
			foreach (ItemDisplayData data2 in tuple.list)
			{
				pData += data2.Serialize(pData);
			}
		}
		return offset;
	}

	[ExtraSerializer]
	public unsafe static int Deserialize(RawDataPool dataPool, int offset, ref (ItemSourceType type, List<ItemDisplayData> list) tuple)
	{
		byte* pData = dataPool.GetPointer(offset);
		byte* pCurrData = pData;
		tuple.type = *(ItemSourceType*)pCurrData;
		pCurrData += 4;
		int listCount = *(int*)pCurrData;
		pCurrData += 4;
		tuple.list?.Clear();
		if (listCount > 0)
		{
			ref List<ItemDisplayData> item = ref tuple.list;
			if (item == null)
			{
				item = new List<ItemDisplayData>();
			}
			for (int index = 0; index < listCount; index++)
			{
				ItemDisplayData data = new ItemDisplayData();
				pCurrData += data.Deserialize(pCurrData);
				tuple.list.Add(data);
			}
		}
		return (int)(pCurrData - pData);
	}

	[ExtraSerializer]
	public unsafe static int Serialize((ItemSourceType type, ResourceInts resource) tuple, RawDataPool dataPool)
	{
		int dataSize = 4 + tuple.resource.GetSerializedSize();
		byte* pData = default(byte*);
		int result = dataPool.Allocate(dataSize, &pData);
		*(ItemSourceType*)pData = tuple.type;
		pData += 4;
		*(ResourceInts*)pData = tuple.resource;
		pData += tuple.resource.GetSerializedSize();
		return result;
	}

	[ExtraSerializer]
	public unsafe static int Deserialize(RawDataPool dataPool, int offset, ref (ItemSourceType type, ResourceInts resource) tuple)
	{
		byte* pData = dataPool.GetPointer(offset);
		byte* pCurrData = pData;
		tuple.type = *(ItemSourceType*)pCurrData;
		pCurrData += 4;
		tuple.resource = *(ResourceInts*)pCurrData;
